import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            vec = (dr, dc)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

found = False
for p in itertools.permutations(range(6)):
    if is_costas(p):
        print(p)
        found = True
        break

print("Found:", found)
